import{Game,validSave}from'./engine.js';
import{RELICS,ZONES,ROOMS,LORE,DIRS,exitsFor,MIRRORS}from'./content.js';
import{Renderer}from'./renderer.js';
import{Sound}from'./audio.js';
const $=id=>document.getElementById(id),key='hollowmere.journey.v1',sound=new Sound();let saved=null,storageOK=true;
try{const raw=localStorage.getItem(key);if(raw){const parsed=JSON.parse(raw);if(validSave(parsed))saved=parsed;}}catch{storageOK=false;}
let game=new Game(saved),renderer=new Renderer($('world'),game),playing=false,saveTimer=null,walkTimer=null,holdTimer=null,lastAction=0,hintLevel=0,icons={},lastSecond=performance.now(),lastFrame=0,solutionData=null;
const modal=$('modal');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const motionReduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
fetch('solutions.json').then(r=>r.ok?r.json():null).then(d=>solutionData=d).catch(()=>{});
renderer.atlas.addEventListener('load',()=>{const sheet=renderer.atlas,s=sheet.width/4;Object.entries(RELICS).forEach(([id,r])=>{if(r.sprite==null)return;const c=document.createElement('canvas');c.width=c.height=80;c.getContext('2d').drawImage(sheet,(r.sprite%4)*s,Math.floor(r.sprite/4)*s,s,s,0,0,80,80);icons[id]=c.toDataURL();});update();});
renderer.props.addEventListener('load',()=>{const sheet=renderer.props,s=sheet.width/4;['bell','hourglass'].forEach((id,i)=>{const c=document.createElement('canvas');c.width=c.height=80;c.getContext('2d').drawImage(sheet,i*s,0,s,s,0,0,80,80);icons[id]=c.toDataURL();});update();});
function icon(id,cls='relic-icon'){const r=RELICS[id];return icons[id]?`<img class="${cls}" src="${icons[id]}" alt="">`:`<span class="${cls}" style="font-size:28px;display:grid;place-items:center;color:var(--gold)">${r.symbol||'✧'}</span>`;}
function save(immediate=false){clearTimeout(saveTimer);const write=()=>{try{localStorage.setItem(key,JSON.stringify(game.snapshot()));storageOK=true;$('save-indicator').textContent='Journey saved';saved=game.snapshot();}catch{storageOK=false;$('save-indicator').textContent='Use Export save in menu';}};if(immediate)write();else saveTimer=setTimeout(write,220);}
function stopWalk(){clearInterval(walkTimer);walkTimer=null;renderer.target=null;}
function stopHold(){clearTimeout(holdTimer);holdTimer=null;document.querySelectorAll('.held').forEach(b=>b.classList.remove('held'));}
function flush(){const events=game.events.splice(0);for(const e of events){if(e.text)$('message').textContent=e.text;if(['chime','solve','beacon','relic','cut','hook','freeze','reveal','wrong','click','bell','memory'].includes(e.type))sound.chime(e.type);if(['chime','solve','beacon','relic','reveal','cut','memory'].includes(e.type))renderer.burst(game.state.x,game.state.y,e.type==='cut'?'#8bae88':'#e8ca81',e.type==='beacon'?60:20);if(e.type==='solve'){renderer.flash=.1;if(navigator.vibrate&&!motionReduced)navigator.vibrate(25);}if(e.type==='arrive'){stopWalk();hintLevel=0;const el=$('room-arrival');el.textContent=e.text;el.classList.remove('arrive');void el.offsetWidth;el.classList.add('arrive');}if(e.type==='relic')relicDialog(e.relic);if(e.type==='beacon')beaconDialog(e.zone);if(e.type==='memory')memoryDialog(e.zone);if(e.type==='story')show('A keeper’s echo','The Last Watch',`<p>${escape(LORE.hub)}</p><p>${escape(e.text)}</p>`);if(e.type==='inscription')inscription();if(e.type==='ending')ending();}update();if(playing)save();}
function doAction(fn){if(!playing||modal.open)return;fn();flush();}
function update(){const s=game.state,r=game.room,z=ZONES[r.zone];$('region-label').textContent=z?z.name:r.type==='ending'?'THE WAY HOME':'THE THRESHOLD';$('room-title').textContent=r.name;$('hearts').innerHTML='<span aria-hidden="true">✧</span> <span style="font-size:11px;letter-spacing:0">Lantern lit</span>';$('hearts').setAttribute('aria-label','Your lantern is lit');$('quest').textContent=r.type==='hub'?(s.beacons.length<4?`Find the ${ZONES[s.beacons.length].beacon.toLowerCase()} beacon`:s.beacons.length===4?'Climb to the observatory':'Bring the light home'):r.type==='ending'?'Leave a light for the next traveler':`${ZONES[r.zone].beacon} beacon · ${Array.from({length:6},(_,i)=>s.rooms[`${z.id}-${i+1}`]?.solved).filter(Boolean).length} / 6 trials`;$('beacon-count').innerHTML=`${s.beacons.length} / 5 <span>beacons</span>`;$('room-number').textContent=z?`${String(r.zone+1).padStart(2,'0')} / ${String(r.index+1).padStart(2,'0')}  ·  ${r.type==='secret'?'FORGOTTEN MEMORY':r.type==='beacon'?'THE BEACON':'HOLLOWMERE'}`:'THE SANCTUARY';$('room-state').textContent=game.data.solved?'✧  REMEMBERED':game.data.frozen>0?`${game.data.frozen} STEPS OUTSIDE TIME`:game.data.timer>0?`${game.data.timer} STEPS REMAIN`:'EXPLORE & DISCOVER';
 $('relic-bar').innerHTML=Object.entries(RELICS).map(([id,r],i)=>`<button class="relic ${s.equipped===id?'active':''} ${game.has(id)?'':'locked'}" data-relic="${id}" aria-label="${game.has(id)?'Equip '+r.name:'Undiscovered relic'}" aria-pressed="${s.equipped===id}" ${game.has(id)?'':'disabled'}>${game.has(id)?icon(id):'<span class="relic-icon" style="display:grid;place-items:center;font-size:23px">◇</span>'}<span>${game.has(id)?r.short:'Unknown'}</span><span class="relic-key">${i+1}</span></button>`).join('');
 $('relic-bar').querySelectorAll('[data-relic]').forEach(b=>b.onclick=()=>{stopWalk();doAction(()=>game.equip(b.dataset.relic));});$('use').textContent=`Use ${RELICS[s.equipped].short.toLowerCase()}`;const n=game.nearest(),names={relic:'Take relic',beacon:game.data.solved?'Inspect':'Kindle',chest:'Remember',portal:'Ascend',keeper:'Listen',rest:'Rest',hearth:game.room.type==='ending'?'Leave the light':'Enter hearth',return:'Return home',mirror:'Turn mirror',valve:'Turn wheel',brazier:'Kindle',resonator:'Sound bell',clock:'Set clock',sluice:'Open sluice',seed:'Awaken',inscription:'Read',vine:'Cut thorns',source:'Wake source'};$('action-label').textContent=n?names[n.type]||'Interact':'Interact';$('action-icon').textContent=n?.type==='mirror'?'↻':n?.type==='keeper'?'◌':n?.type==='return'?'⌂':'✧';$('undo').disabled=game.history.length===0;}
function show(eyebrow,title,copy,buttons=''){stopWalk();stopHold();$('modal-content').innerHTML=`<button class="modal-close" aria-label="Close dialog">×</button><div class="modal-eyebrow">${escape(eyebrow).toUpperCase()}</div><h3 class="modal-title">${escape(title)}</h3><div class="modal-copy">${copy}</div>${buttons}`;$('modal-content').querySelector('.modal-close').onclick=()=>modal.close();if(!modal.open)modal.showModal();}
function help(){show('Your journey','A light in the dark',`<p><strong>Tap a floor tile</strong> to walk there, or hold the direction buttons. Tap an object to approach it, then press the gold action button.</p><p><strong>Choose a relic</strong> from the six slots. The small button beneath Interact uses the selected relic. Read each room’s inscription with <strong>?</strong>.</p><p>Push weights by walking into them. Tap a distant brass ring to aim and cast the hook. New relics explain their own abilities.</p><p>Experiment freely: <strong>Undo</strong> takes back a move. The pause menu can reset the current puzzle. Hints reveal a little more each time.</p><p class="help-keys">Keyboard: WASD / arrows to move · E / Enter to interact · Space to use relic · 1–6 to equip · Z to undo · M map · J journal · Esc pause.</p><p class="fine">Progress saves on this browser and device. Export a save from the pause menu to keep a backup or move to another device.</p>`);}
function start(fresh=false){if(fresh){game=new Game();renderer.game=game;}playing=true;$('title-screen').hidden=true;$('play-screen').hidden=false;update();$('message').textContent=game.room.clue;renderer.lastRoom='';save();if(fresh)show('Welcome to Hollowmere','The Last Watch',`<p>${LORE.hub}</p><p>You carry the last lantern. Five beacons wait in the dark.</p><p class="fine">Tap a tile to walk. Tap the northern arch to enter the garden. Your journey saves automatically.</p>`,`<div class="modal-buttons"><button class="primary" id="set-out">Carry the light →</button></div>`);if($('set-out'))$('set-out').onclick=()=>modal.close();}
function title(){stopWalk();stopHold();save(true);playing=false;$('play-screen').hidden=true;$('title-screen').hidden=false;refreshTitle();modal.close();}
function refreshTitle(){if(saved){$('continue').hidden=false;$('continue').textContent='Continue your journey';$('begin').textContent='Begin a new journey →';$('begin').className='secondary';$('continue').className='primary';$('save-summary').textContent=`${ROOMS[saved.room].name} · ${saved.beacons.length}/5 beacons · ${Math.floor(saved.seconds/60)} minutes`;}else{$('continue').hidden=true;}if(!storageOK)$('save-summary').textContent='Browser storage is unavailable. Use Export save in the menu to keep your journey.';}
function confirmNew(){if(!saved){start(true);return;}show('A new journey','Begin again?',`<p>Your current journey will be replaced on this device. You can export it first from the pause menu.</p>`,`<div class="modal-buttons"><button class="secondary" id="cancel-new">Keep my journey</button><button class="primary" id="confirm-new">Begin again</button></div>`);$('cancel-new').onclick=()=>modal.close();$('confirm-new').onclick=()=>{modal.close();start(true);};}
function relicDialog(id){const r=RELICS[id],z=ZONES[game.room.zone];show('Relic discovered',r.name,`${icon(id,'relic-discovery')}<p>${escape(r.description)}</p><p class="help-keys">${escape(r.use)}</p><p class="fine">${escape(z.intro)}</p>`,`<div class="modal-buttons"><button class="primary" id="relic-ready">Take it with you →</button></div>`);$('relic-ready').onclick=()=>modal.close();}
function beaconDialog(i){const z=ZONES[i];show('Beacon rekindled',`The ${z.beacon} Light`,`<p>${escape(z.epilogue)}</p><p>${game.state.beacons.length<5?'A new path has opened at the Last Watch. Use the return stone to travel home.':'All five beacons are burning. Return to the Last Watch and carry the light to the hearth.'}</p><div class="stats"><div><strong>${game.state.beacons.length}/5</strong>BEACONS</div><div><strong>${game.state.visited.length}</strong>ROOMS FOUND</div><div><strong>${game.state.memories.length}/5</strong>MEMORIES</div></div>`,`<div class="modal-buttons"><button class="secondary" id="stay">Keep exploring</button><button class="primary" id="go-home">Return home →</button></div>`);$('stay').onclick=()=>modal.close();$('go-home').onclick=()=>{modal.close();game.enter('hub');flush();};}
function memoryDialog(i){const z=ZONES[i];show('A keeper remembered',z.memory,`<p>${escape(z.memoryText)}</p><p class="fine">${game.state.memories.length} of 5 memories found. This memory has been added to your journal.</p>`);}
function inscription(){show('The room’s inscription',game.room.name,`<p style="font-family:Georgia,serif;font-size:19px;color:var(--gold)">“${escape(game.room.clue)}”</p><p class="fine">${game.data.solved?'This room has been remembered.':`Trial: ${({weights:'stone weights',sequence:'ordered flames',runes:'hidden marks',anchors:'hook crossings',valves:'pressure wheels',mirrors:'reflected light',resonance:'listening runes',timed:'borrowed time',vines:'sleeping seeds'})[game.room.type]||'exploration'}`}</p>`,`<div class="modal-buttons"><button class="secondary" id="read-hint">A little help</button><button class="primary" id="back-room">Back to the room</button></div>`);$('back-room').onclick=()=>modal.close();$('read-hint').onclick=hint;}
function hint(){game.state.hints++;show('A little help',game.room.name,`<p class="hint-step">${escape(game.hint(hintLevel))}</p><p class="fine">Hint ${Math.min(hintLevel+1,3)} of 3. No penalty for asking.</p>`,`<div class="modal-buttons"><button class="secondary" id="more-hint">${hintLevel<2?'A clearer hint':'Puzzle solution'}</button><button class="primary" id="try-again">Let me try</button></div>`);$('more-hint').onclick=()=>{if(hintLevel<2){hintLevel++;hint();}else solution();};$('try-again').onclick=()=>modal.close();save();}
function echoSolution(){const notes=game.data.notes,n=notes.length;for(let mask=0;mask<2**n;mask++){const a=[...notes],seq=[];for(let i=0;i<n;i++)if(mask>>i&1){seq.push(i+1);for(const j of new Set([(i+n-1)%n,i,(i+1)%n]))a[j]=1-a[j];}if(a.every(Boolean))return seq;}return[];}
function mirrorSolution(){const objs=game.data.objects.filter(o=>o.type==='mirror'),old=objs.map(o=>o.angle),lit=game.data.lit;game.data.lit=true;let result=null;for(let mask=0;mask<2**objs.length;mask++){objs.forEach((o,i)=>o.angle=mask>>i&1);if(game.beam().hit){result=objs.map(o=>o.angle?'\\':'/');break;}}objs.forEach((o,i)=>o.angle=old[i]);game.data.lit=lit;return result;}
function solution(){const r=game.room;let text=game.hint(2);if(r.type==='resonance'){const seq=echoSolution();text=seq.length?`From the current pattern, sound the Echo Bell beside rune${seq.length>1?'s':''} ${seq.join(', ')}. The order does not matter.`:'All runes are already lit.';}if(r.type==='mirrors')text=`Wake the source with the prism, then set mirrors 1 onward to: ${(mirrorSolution()||[]).join('  ·  ')}. A slash / slopes upward to the right; a backslash \\ slopes downward to the right.`;if(r.type==='weights'){const sol=solutionData?.[r.variant];text=sol?`Reset this room first. From the reset position, follow these directions. Each letter is one step (U up, D down, L left, R right); pushing happens automatically.\n\n${sol.match(/.{1,24}/g).join('\n')}`:'Push each weight onto a plate. Reset the room for a fresh start, and leave yourself space on every side.';}show('Puzzle solution',r.name,`<p style="white-space:pre-wrap;overflow-wrap:anywhere">${escape(text)}</p>`);}
function journal(){const s=game.state;show('Field notes','The Keeper’s Journal',`<p>${escape(game.room.clue)}</p><div class="stats"><div><strong>${s.visited.length}/47</strong>CHAMBERS</div><div><strong>${Object.values(s.rooms).filter(r=>r.solved).length}</strong>REMEMBERED</div><div><strong>${Math.floor(s.seconds/60)}</strong>MINUTES</div></div><div class="journal-entry"><strong>Your next step</strong><p>${escape(s.beacons.length<5?`Rekindle the ${ZONES[s.beacons.length].beacon} beacon in ${ZONES[s.beacons.length].name}.`:'Return to the Last Watch. Enter the hearth and leave the lantern.')}</p></div>${Object.entries(RELICS).filter(([id])=>game.has(id)).map(([id,r])=>`<div class="journal-entry"><strong>${escape(r.name)}</strong><p>${escape(r.use)}</p></div>`).join('')}${s.memories.map(i=>`<div class="journal-entry"><strong>${escape(ZONES[i].memory)}</strong><p>${escape(ZONES[i].memoryText)}</p></div>`).join('')}<div class="menu-list"><button id="journal-solution">Puzzle solutions · current room</button></div>`);$('journal-solution').onclick=solution;}
function map(zone=game.room.zone){const s=game.state;const selected=zone<0||zone>4?-1:zone;let body=`<p class="fine">Gold is your current room. ✧ means remembered. Select a discovered room to read its inscription. Lit beacons and the sanctuary allow travel.</p><div class="map-tabs"><button data-zone="-1" class="${selected===-1?'active':''}">Sanctuary</button>${ZONES.map((z,i)=>`<button data-zone="${i}" class="${selected===i?'active':''}" ${s.visited.includes(z.id+'-0')?'':'disabled'}>${z.short}</button>`).join('')}</div>`;
 if(selected===-1){body+=`<div class="menu-list"><button data-travel="hub">⌂ The Last Watch · return to sanctuary</button>${ZONES.map((z,i)=>`<button data-travel="${z.id}-0" ${s.beacons.length>=i?'':'disabled'}>${i<s.beacons.length?'✧':'◇'} ${z.name} ${i>s.beacons.length?'· sealed':''}</button>`).join('')}</div>`;}else{body+='<div class="map-grid">';const z=ZONES[selected];for(let y=0;y<3;y++)for(let x=0;x<4;x++){const r=Object.values(ROOMS).find(r=>r.zone===selected&&r.coord[0]===x&&r.coord[1]===y);if(!r){body+='<div></div>';continue;}const seen=s.visited.includes(r.id);body+=`<button class="map-room ${r.id===s.room?'current':''} ${seen?'':'unseen'} ${s.rooms[r.id]?.solved?'complete':''}" data-room="${r.id}" ${seen?'':'disabled'}>${seen?escape(r.name):'Unexplored'}</button>`;}body+='</div>';body+=`<p class="fine">Route: Landing ↑ Trial 1 ↑ Trial 2 → Trial 3 ↓ Trial 4 → Trial 5 ↑ Trial 6 → Beacon. The optional memory lies south of Trial 4.</p>`;if(s.beacons.includes(selected))body+=`<div class="menu-list"><button data-travel="${z.id}-7">Travel to the ${z.beacon} Beacon</button></div>`;}
 show('A map of the forgotten','Hollowmere',body);document.querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>map(Number(b.dataset.zone)));document.querySelectorAll('[data-travel]').forEach(b=>b.onclick=()=>{modal.close();game.enter(b.dataset.travel);flush();});document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{const r=ROOMS[b.dataset.room];show(ZONES[r.zone].name,r.name,`<p>${escape(r.clue)}</p><p class="fine">${s.rooms[r.id]?.solved?'Remembered':'Still waiting'}</p>`,`<div class="modal-buttons"><button class="secondary" id="return-map">Back to map</button></div>`);$('return-map').onclick=()=>map(selected);});}
function menu(){show('Take a breath','The journey can wait',`<p class="fine">${escape(game.room.name)} · ${Math.floor(game.state.seconds/60)} minutes · ${game.state.beacons.length}/5 beacons</p><div class="menu-list"><button id="resume">Continue exploring</button><button id="sound-toggle">Sound: ${sound.enabled?'on':'off'}</button><button id="menu-help">How to play</button><button id="reset-room">Reset this room’s puzzle</button><button id="menu-home">Return to the sanctuary</button><button id="export">Export save</button><button id="import">Import save</button><button id="quit">Save & return to title</button></div>`);$('resume').onclick=()=>modal.close();$('sound-toggle').onclick=async()=>{await sound.toggle();menu();};$('menu-help').onclick=help;$('reset-room').onclick=()=>{modal.close();game.resetRoom();flush();};$('menu-home').onclick=()=>{modal.close();game.enter('hub');flush();};$('export').onclick=exportSave;$('import').onclick=importSave;$('quit').onclick=title;}
function exportSave(){save(true);const blob=new Blob([JSON.stringify(game.snapshot(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='hollowmere-journey.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>2000000)throw Error('That file is too large to be a Hollowmere save.');const data=JSON.parse(await file.text());if(!validSave(data))throw Error('This does not look like a valid Hollowmere journey.');const candidate=new Game(data);for(const d of Object.values(candidate.state.rooms)){if(!Array.isArray(d.grid)||d.grid.length!==13||d.grid.some(row=>!Array.isArray(row)||row.length!==17)||!Array.isArray(d.objects))throw Error('The room data in this save is damaged.');}show('Import journey','Continue this journey?',`<p>${escape(ROOMS[data.room].name)} · ${data.beacons.length}/5 beacons</p><p>This replaces the current journey on this device.</p>`,`<div class="modal-buttons"><button class="secondary" id="cancel-import">Cancel</button><button class="primary" id="apply-import">Import journey</button></div>`);$('cancel-import').onclick=menu;$('apply-import').onclick=()=>{game=candidate;renderer.game=game;modal.close();update();save(true);};}catch(e){show('Save could not be loaded','Keep your lantern',`<p>${escape(e.message)}</p><p>Your current journey has not been changed.</p>`);}};input.click();}
function ending(){const s=game.state;show('The last lantern','And the road goes on.',`<p>${LORE.ending}</p>${s.memories.length===5?'<p style="color:var(--gold)">You carried all five keepers home with you. In the doorway, five familiar shadows pause. Then they step into the morning.</p>':'<p class="fine">There are still keeper memories to find. You may return and explore the monastery.</p>'}<div class="stats"><div><strong>${Math.floor(s.seconds/60)}</strong>MINUTES</div><div><strong>${s.visited.length}/47</strong>CHAMBERS</div><div><strong>${s.memories.length}/5</strong>MEMORIES</div></div>`,`<div class="modal-buttons"><button class="secondary" id="ending-title">Return to title</button><button class="primary" id="ending-explore">Keep exploring →</button></div>`);$('ending-title').onclick=title;$('ending-explore').onclick=()=>{modal.close();game.enter('hub');flush();};save(true);}
function findPath(goal){const s=game.state,queue=[[s.x,s.y]],seen=new Set([`${s.x},${s.y}`]),parents=new Map();let end=null;while(queue.length){const[x,y]=queue.shift();if(goal(x,y)){end=[x,y];break;}for(const[dx,dy]of Object.values(DIRS)){const nx=x+dx,ny=y+dy,k=`${nx},${ny}`;if(seen.has(k)||!game.passable(nx,ny))continue;if(game.tile(nx,ny)==='D'&&!goal(nx,ny))continue;if(game.data.revealed&&!game.data.solved&&game.objectsAt(nx,ny).some(o=>o.type==='rune')&&!goal(nx,ny))continue;seen.add(k);parents.set(k,[x,y]);queue.push([nx,ny]);}}if(!end)return null;const path=[];while(end[0]!==s.x||end[1]!==s.y){path.unshift(end);end=parents.get(end.join(','));}return path;}
function tapWorld(e){if(!playing||modal.open)return;stopWalk();const p=renderer.point(e);if(p.x<0||p.y<0||p.x>=17||p.y>=13)return;const s=game.state,objects=game.objectsAt(p.x,p.y),anchor=objects.find(o=>o.type==='anchor');if(anchor&&game.has('hook')&&(p.x===s.x||p.y===s.y)&&(p.x!==s.x||p.y!==s.y)){game.equip('hook');s.face=[Math.sign(p.x-s.x),Math.sign(p.y-s.y)];game.use('hook');flush();return;}const object=objects.find(o=>game.solid(o)||o.type==='seed');if(object&&Math.abs(p.x-s.x)+Math.abs(p.y-s.y)<=1){if(object.type==='crate')doAction(()=>game.move(p.x-s.x,p.y-s.y));else doAction(()=>game.interact(object));return;}const goal=object?(x,y)=>Math.abs(x-p.x)+Math.abs(y-p.y)===1:(x,y)=>x===p.x&&y===p.y;const path=findPath(goal);if(!path){game.say('There is no clear walking path. A relic may open the way.');flush();return;}renderer.target=p;let index=0;walkTimer=setInterval(()=>{if(modal.open||index>=path.length){stopWalk();if(object){game.say(game.description(object));flush();}return;}const next=path[index++],dx=next[0]-game.state.x,dy=next[1]-game.state.y;if(Math.abs(dx)+Math.abs(dy)!==1||!game.move(dx,dy)){stopWalk();}flush();},110);}
$('world').addEventListener('pointerdown',tapWorld);
document.querySelectorAll('[data-dir]').forEach(b=>{const[dx,dy]=b.dataset.dir.split(',').map(Number);b.addEventListener('pointerdown',e=>{if(!playing||modal.open)return;e.preventDefault();b.setPointerCapture(e.pointerId);stopWalk();stopHold();b.classList.add('held');doAction(()=>game.move(dx,dy));const repeat=()=>{doAction(()=>game.move(dx,dy));holdTimer=setTimeout(repeat,125);};holdTimer=setTimeout(repeat,280);});b.addEventListener('pointerup',stopHold);b.addEventListener('pointercancel',stopHold);b.addEventListener('lostpointercapture',stopHold);});
$('interact').onclick=()=>{stopWalk();doAction(()=>{const n=game.nearest();if(n?.type==='vine'&&game.state.equipped==='blade')game.use('blade');else game.interact();});};$('use').onclick=()=>{stopWalk();doAction(()=>game.use());};$('undo').onclick=()=>{stopWalk();doAction(()=>game.undo());};$('menu').onclick=menu;$('journal').onclick=journal;$('map').onclick=()=>map();$('inspect').onclick=inscription;$('hint').onclick=hint;$('begin').onclick=confirmNew;$('continue').onclick=()=>start();$('title-help').onclick=help;$('title-sound').onclick=async()=>{await sound.toggle();$('title-sound').textContent=sound.enabled?'♫':'♪';$('title-sound').setAttribute('aria-label',sound.enabled?'Disable sound':'Enable sound');};
window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(playing&&!modal.open){e.preventDefault();menu();}return;}if(!playing||modal.open||e.ctrlKey||e.metaKey||e.altKey)return;const k=e.key.toLowerCase(),movement={arrowup:[0,-1],w:[0,-1],arrowdown:[0,1],s:[0,1],arrowleft:[-1,0],a:[-1,0],arrowright:[1,0],d:[1,0]};if(movement[k]){e.preventDefault();if(performance.now()-lastAction<90)return;lastAction=performance.now();stopWalk();doAction(()=>game.move(...movement[k]));return;}if([' ','enter','e','z','m','j','r','1','2','3','4','5','6'].includes(k))e.preventDefault();if(e.repeat)return;if(k===' ')doAction(()=>game.use());if(k==='enter'||k==='e')$('interact').click();if(k==='z')doAction(()=>game.undo());if(k==='m')map();if(k==='j')journal();if(k==='r')inscription();if(/^[1-6]$/.test(k))doAction(()=>game.equip(Object.keys(RELICS)[Number(k)-1]));});
modal.addEventListener('click',e=>{if(e.target===modal){const b=modal.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)modal.close();}});
window.addEventListener('blur',()=>{stopWalk();stopHold();if(playing)save(true);});document.addEventListener('visibilitychange',()=>{stopWalk();stopHold();if(playing)save(true);lastSecond=performance.now();});window.addEventListener('pagehide',()=>{if(playing)save(true);});
function frame(now){if(playing&&!document.hidden){if(now-lastFrame>=32){renderer.draw(now);lastFrame=now;}sound.update();if(now-lastSecond>=1000){if(!modal.open){game.state.seconds+=Math.floor((now-lastSecond)/1000);if(game.state.seconds%30===0)save();}lastSecond=now;}}else lastSecond=now;requestAnimationFrame(frame);}refreshTitle();update();requestAnimationFrame(frame);
